'use strict';

// MODULES //

var dtypes = require( '@stdlib/ndarray-dtypes' );
var glastIndexEqual = require( '@stdlib/blas-ext-base-ndarray-glast-index-equal' );
var dlastIndexEqual = require( '@stdlib/blas-ext-base-ndarray-dlast-index-equal' );
var slastIndexEqual = require( '@stdlib/blas-ext-base-ndarray-slast-index-equal' );
var factory = require( '@stdlib/ndarray-base-binary-reduce-strided1d-dispatch-factory' );


// VARIABLES //

var idtypes0 = dtypes( 'all' ); // first input ndarray
var idtypes1 = dtypes( 'all' ); // second input ndarray
var idtypes2 = dtypes( 'integer_index_and_generic' ); // from index ndarray
var odtypes = dtypes( 'integer_index_and_generic' );
var policies = {
	'output': 'integer_index_and_generic',
	'casting': 'none'
};
var table = {
	'types': [
		'float64',
		'float64',
		'float32',
		'float32'

		// FIXME: add specialized support for `clastIndexEqual` and `zlastIndexEqual` once the corresponding packages are implemented
	],
	'fcns': [
		dlastIndexEqual,
		slastIndexEqual
	],
	'default': glastIndexEqual
};


// MAIN //

/**
* Returns the index of the last element in an ndarray which is equal to a corresponding element in another ndarray along an ndarray dimension.
*
* @private
* @name lastIndexEqual
* @type {Function}
* @param {ndarrayLike} x - first input ndarray
* @param {ndarrayLike} y - second input ndarray
* @param {ndarrayLike} fromIndex - indices from which to begin searching
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @param {*} [options.dtype] - output ndarray data type
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} third argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} output ndarray
*
* @example
* var Float64Array = require( '@stdlib/array-float64' );
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var ndarray = require( '@stdlib/ndarray-ctor' );
*
* // Create data buffers:
* var xbuf = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0 ] );
* var ybuf = new Float64Array( [ 0.0, 2.0, 0.0, 2.0, 2.0, 2.0 ] );
*
* // Define the shape of the input arrays:
* var sh = [ 6 ];
*
* // Define the array strides:
* var sx = [ 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create input ndarrays:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
* var y = new ndarray( 'float64', ybuf, sh, sx, ox, 'row-major' );
*
* // Create a from index ndarray:
* var fromIndex = scalar2ndarray( -1, {
*     'dtype': 'int32'
* });
*
* // Perform operation:
* var out = lastIndexEqual( x, y, fromIndex );
* // returns <ndarray>[ 3 ]
*/
var lastIndexEqual = factory( table, [ idtypes0, idtypes1, idtypes2 ], odtypes, policies ); // eslint-disable-line max-len


// EXPORTS //

module.exports = lastIndexEqual;

// exports: { "assign": "lastIndexEqual.assign" }
