'use strict';

/**
* Return the index of the last element in an ndarray which is equal to a corresponding element in another ndarray along an ndarray dimension.
*
* @module @stdlib/blas-ext-last-index-equal
*
* @example
* var Float64Array = require( '@stdlib/array-float64' );
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var ndarray = require( '@stdlib/ndarray-ctor' );
* var lastIndexEqual = require( '@stdlib/blas-ext-last-index-equal' );
*
* // Create a data buffer:
* var xbuf = new Float64Array( [ 0.0, 0.0, 3.0, 4.0, 0.0, 0.0 ] );
*
* // Define the shape of the input array:
* var sh = [ 2, 3 ];
*
* // Define the array strides:
* var sx = [ 3, 1 ];
*
* // Define the index offset:
* var ox = 0;
*
* // Create an input ndarray:
* var x = new ndarray( 'float64', xbuf, sh, sx, ox, 'row-major' );
*
* // Create a second input ndarray:
* var y = scalar2ndarray( 0.0, {
*     'dtype': 'float64'
* });
*
* // Perform operation:
* var out = lastIndexEqual( x, y );
* // returns <ndarray>[ 1, 2 ]
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils-define-nonenumerable-read-only-property' );
var main = require( './main.js' );
var assign = require( './assign.js' );


// MAIN //

setReadOnly( main, 'assign', assign );


// EXPORTS //

module.exports = main;

// exports: { "assign": "main.assign" }
